from __future__ import annotations

import json
from typing import Literal, List, TypedDict, Unpack, Optional

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class ConferenceMember(TypedDict):
    role: Literal["moderator", "speaker"]


class ConferenceRole(TypedDict):
    permissions: int


class ConferenceUpdateKwargs(TypedDict, total=False):
    name: str
    type: Literal["equitable", "webinar"]
    creator: str
    members: dict[str, ConferenceMember]
    roles: dict[str, ConferenceRole]


class ConferenceNewCreateKwargs(TypedDict, total=False):
    type: Literal["equitable", "webinar"]
    pinRequired: Optional[bool]
    members: dict[str, ConferenceMember]
    roles: dict[str, ConferenceRole]


class CalleventsGetCallLogKwargs(TypedDict, total=False):
    offset: Optional[int]
    limit: Optional[int]
    order: Optional[str]
    start: Optional[str]
    end: Optional[str]


class CalleventsAddEventsKwargs(TypedDict, total=False):
    event: str
    time: int
    conference_session_id: str
    type: str
    conference_url: str
    room_name: str
    creator_uid: str
    dir: Optional[str]
    instance: Optional[str]
    session_guid: Optional[str]
    hangup_reason: Optional[str]
    uid: Optional[str]


class ConferencesMethods(BaseClient):
    """
    Методы группы 'Конференции' из https://im-docs.corp.mail.ru/
    """

    @tracer.start_as_current_span("conferences.rapi_conference_create")
    @api_version_check(min_version=8, max_version=99)
    def rapi_conference_create(
        self,
        name: str,
        _type: Literal["equitable", "webinar"],
        participants: List[str],
        callParticipants: bool,
        pinRequired: bool,
    ) -> dict:
        """
        Создание новой конференции

        :param name: Название конференции
        :param _type: Тип конференции (равноправная или вебинар)
        :param participants: Список участников конференции (sn'ы),
        которым нужно отправить ссылку на конференцию от имени пользователя,
        создающего конференцию.
        :param callParticipants: Нужно ли выполнять обратный
        звонок всем участникам конференции.
        :param pinRequired:
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/conference/create",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "name": name,
                    "type": _type,
                    "participants": participants,
                    "callParticipants": callParticipants,
                    "pinRequired": pinRequired,
                },
            },
        )

    @tracer.start_as_current_span("conferences.rapi_conference_get")
    @api_version_check(min_version=103)
    def rapi_conference_get(self, conference_id: str) -> dict:
        """
        Запросить параметры конференции
        Запрос параметров конференции
        :param conference_id: Название конференции
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/conference/get",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"id": conference_id},
            },
        )

    @tracer.start_as_current_span("conferences.rapi_conference_update")
    @api_version_check(min_version=103)
    def rapi_conference_update(self, conference_id: str, **kwargs: Unpack[ConferenceUpdateKwargs]) -> dict:
        """
        Обновить параметры конференции
        Обновление параметров конференции
        :param conference_id: ID конференции.
        :param name: Название конференции
        :param conf_type: Тип конференции (равноправная или вебинар)
        :param creator: SN создателя конференции.
        :param members: role string example: speaker Роль участника
        :param roles: permissions number example: 42 Битовая маска, содержащая набор разрешений для данной роли:
        * Управление параметрами конференции - 1
        * Управление медиа - 2
        * Управление комнатой ожидания - 4
        * Удаление участников - 8
        * Управление записью звонка - 16
        * Отправка аудио - 32
        * Отправка видео - 64
        * Демонстрация экрана - 128
        * Просмотр реакций - 256
        * Отправка реакций - 512
        * Просмотр сообщений в чате - 1024
        * Отправка сообщений в чат - 2048
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/conference/update",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"id": conference_id, **kwargs},
            },
        )

    @tracer.start_as_current_span("conferences.rapi_conference_create_new")
    @api_version_check(min_version=100)
    def rapi_conference_create_new(self, name: str, **kwargs: Unpack[ConferenceNewCreateKwargs]) -> dict:
        """
        Создание новой конференции

        :param name: Название конференции
        :param _type: Тип конференции (равноправная или вебинар)
        :param members: role string example: speaker Роль участника
        :param roles: permissions number example: 42 Битовая маска, содержащая набор разрешений для данной роли:
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/conference/create",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"name": name, **kwargs},
            },
        )

    @tracer.start_as_current_span("conferences.rapi_callevents_add_events")
    @api_version_check(min_version=111)
    def rapi_callevents_add_events(self, **kwargs: Unpack[CalleventsAddEventsKwargs]) -> dict:
        """
        Добавить новые события статистики/мониторинга

        :param event: тип события
        :param time: timestamp в миллисекундах
        :param conference_session_id: conference session id
        :param type: [focus, p2p],
        :param conference_url: conference url,
        :param room_name: имя создателя,
        :param creator_uid: creator uid,

        :return: тело ответа сервера
        """
        kwargs_json = json.dumps(kwargs)

        return self.post(
            "rapi/callevents/addEvents",
            headers={"Content-Type": "application/json;charset=utf-8"},
            json={"reqId": self.getReqId(), "aimsid": self.aimsid, "params": {"events": f"{kwargs_json}"}},
        )

    @tracer.start_as_current_span("conferences.rapi_callevents_get_call_log")
    @api_version_check(min_version=111)
    def rapi_callevents_get_call_log(self, **kwargs: Unpack[CalleventsGetCallLogKwargs]) -> dict:
        """
        Получить данные по звонкам, в которых участвовал конкретный пользователь

        :param offset: индекс, начиная с которого возвращать записи, для постраничного вывода, по умолчанию 0
        :param limit: сколько звонков возвращать
        :param order: порядок, по времени захода в звонок 'asc' - ascending 'desc' - descending
        :param start: начало диапазона дат. В одном из форматов - RFC3339, RFC1123, UnixDate, ANSIC, timestamp
        :param end: конец диапазона дат. В одном из форматов - RFC3339, RFC1123, UnixDate, ANSIC, timestamp

        :return: тело ответа сервера
        """
        return self.post(
            "rapi/callevents/getCallLog",
            headers={"Content-Type": "application/json;charset=utf-8"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"sn": self.uin, **kwargs},
            },
        )
